pragma solidity 0.8.36;
uint256 constant FREE = 5;
function bump(uint256 value) pure returns (uint256) { return value + 1; }
library Math { function doubled(uint256 value) internal pure returns (uint256) { return value * 2; } function linkedAdd(uint256 left, uint256 right) external pure returns (uint256) { return left + right; } }

